      S.three.label('Serial (open chain)', [-0.15, 0, 1.25], ''); S.three.label('Parallel: Delta (closed chains)', [DL.ox, 0, 1.25], '');
      const G = S.dg = new THREE.Group(); G.position.x = DL.ox; sc.add(G);
