    step(S) { if (S.auto) { const t = S.t; S.setParam('a', +(20 + 40 * Math.sin(0.6 * t)).toFixed(1), true); S.setParam('b', +(25 + 35 * Math.sin(0.5 * t + 2)).toFixed(1), true); S.setParam('c', +(25 + 35 * Math.sin(0.7 * t + 4)).toFixed(1), true); } },
