      S.set('f', r.f); S.set('D', r.D * 100); S.set('ton', r.D * T * 1e6); S.set('toff', (1 - r.D) * T * 1e6); S.set('vavg', r.D * p.Vdc); S.set('bits', p.mode === 'timer' ? r.bits : '—'); S.set('n', S.w); S.set('rip', rip);
