      if (p.bus === 'uart') { bits.push({ v: 0, f: 'start' }); lsb.forEach((v, i) => bits.push({ v, f: 'D' + i })); if (p.par) bits.push({ v: lsb.reduce((a, c) => a ^ c, 0), f: 'parity (even)' }); bits.push({ v: 1, f: 'stop' }); return { bits, lines: ['TX'] }; }
